#include <stdio.h>
/* 握手定理：无向图所有顶点的度数之和必为偶数，且等于 2*边数 */
int main(void){
    int deg[]={2,2,3,1};   /* 取自 ex01 的度数 */
    int n=4, sum=0;
    for(int i=0;i<n;i++) sum+=deg[i];
    int edges=sum/2;       /* 每条边被两个端点各数一次 */
    printf("sum(deg)=%d, 2*edges=%d, edges=%d\n", sum, 2*edges, edges);
    return 0;
}
